[
  {
    "id": "TP01",
    "name": "exhaustive_command_decode",
    "action": "Apply every 8-bit command value, then apply 8'hFF after each value to exercise an unsupported command.",
    "variation": "cmd: 8'h00-8'hFF; follow-up command: 8'hFF",
    "observation": "Observe get_addr, get_mode, get_data, send_data, enable_cont, enable_regs, wait_dummy, error, and reg_sel.",
    "branch_intent": "Exercises command decoding across the full input space and repeated unsupported-command behavior, covering recognized and unrecognized command handling."
  }
]

[
  {
    "id": "TP01",
    "name": "dual_input_truth_table",
    "action": "Apply all four combinations of a and b, allowing the combinational outputs to settle after each input assignment.",
    "variation": "Input combinations: (0,0), (0,1), (1,0), (1,1)",
    "observation": "Observe out_and, out_or, out_xor, out_nand, out_nor, out_xnor, and out_anotb for every input combination.",
    "branch_intent": "Exercises every binary input case across all seven logic functions, covering complementary, symmetric, and directional output behavior."
  }
]

[
  {
    "id": "TP01",
    "name": "select_operand_source",
    "action": "Apply ALUSrc=0 with ReadData2=00000000, FFFFFFFF, and 12345678; apply ALUSrc=1 with Sign_Extnd_out=80000000 and 7FFFFFFF.",
    "variation": "ALUSrc: 0, 1; ReadData2: 00000000, FFFFFFFF, 12345678; Sign_Extnd_out: 00000000, 80000000, 7FFFFFFF",
    "observation": "Observe ALUIn2 for register-data selection when ALUSrc=0 and immediate selection when ALUSrc=1.",
    "branch_intent": "Exercises both operand-selection behaviors and observes how ALUSrc determines whether register data or the immediate supplies ALUIn2."
  }
]

[
  {
    "id": "TP01",
    "name": "exhaustive_hex_dp_decode",
    "action": "Apply each 4-bit hexadecimal input with the decimal-point input set to both values, covering the complete input combination space.",
    "variation": "hex: 0-15; dp: 0,1",
    "observation": "Observe all eight bits of sseg for the seven-segment pattern and decimal-point output across every input combination.",
    "branch_intent": "Exercises every hexadecimal decoding branch, including the default F glyph, and demonstrates decimal-point independence for complete combinational input coverage."
  }
]

[
  {
    "id": "TP01",
    "name": "parallel_word_patterns",
    "action": "Apply paired 32-bit patterns to transformation_array_input0 and transformation_array_input1, including uniform values, varied digits, and distinct patterns across the two words.",
    "variation": "Patterns: 00000000, FFFFFFFF, 01234567/89ABCDEF, 13579BDF/00000000, 00000000/2468ACE0, 80000001/7FFFFFFE",
    "observation": "Observe transformation_array_output0 and transformation_array_output1 for the corresponding transformed words across all eight four-bit digits.",
    "branch_intent": "Exercises parallel per-digit doubling across uniform, varied, and boundary-containing data, including one-word-at-a-time activity to assess independent word processing."
  }
]

[
  {
    "id": "TP01",
    "name": "combinational_opcode_decode_sweep",
    "action": "Apply every 5-bit opcode major value with every func3 value and four func7 patterns, varying the opcode's two low bits across all combinations.",
    "variation": "opcode major: 5-bit values 0-31; opcode low bits: 0-3; func3: 0-7; func7 pattern: 0-3",
    "observation": "Observe ExtOp, Branch, MemRead, MemWrite, ALUsrc, ALUAsrc, ALUBsrc, MemToReg, and RegWrite.",
    "branch_intent": "Exercises opcode decoding and func3 and func7 combinations across the input space, including supported and unsupported encodings, to characterize control outputs."
  }
]

[
  {
    "id": "TP01",
    "name": "operand_and_carry_combinations",
    "action": "Apply two 2-bit operands and a carry input, varying all inputs across their complete binary ranges.",
    "variation": "a,b: 00-11; cin: 0-1; all 32 combinations",
    "observation": "Observe the 2-bit sum and carry output for each input combination.",
    "branch_intent": "Exercises the adder across every operand and carry-input combination, covering result and carry behavior throughout its input space."
  }
]

[
  {
    "id": "TP01",
    "name": "control_input_sweep",
    "action": "Apply every combination of state, Rd, Wr, valid, hit, dirty, and stall across the complete input space.",
    "variation": "state: 0-15; Rd, Wr, valid, hit, dirty, stall: all binary combinations",
    "observation": "Observe next_state, mem_offset, cache_offset, wr, rd, write, comp, enable, cache_stall, and potentialHit.",
    "branch_intent": "Exercise the sequencer's input-dependent control behavior across all port combinations, including request selection, cache status, stalls, and transfer offsets."
  }
]

[
  {
    "id": "TP01",
    "name": "exhaustive_opcode_decode",
    "action": "Apply every 6-bit instruction opcode, then apply 6'h3F after each opcode to exercise unsupported-opcode recovery.",
    "variation": "i_instrCode: all 64 values (0x00-0x3F); recovery input: 0x3F",
    "observation": "Observe o_regDst, o_jump, o_beq, o_bne, o_memToReg, o_aluOp, o_memWrite, o_aluSrc_op2, o_regWrite, o_extOp, and o_unknown_command.",
    "branch_intent": "Exercises the complete opcode decode and transitions from each decoded input to an unsupported instruction, covering output selection and recovery behavior."
  }
]

[
  {
    "id": "TP01",
    "name": "exhaustive_byte_substitution",
    "action": "Apply every 8-bit value from 0x00 through 0xFF to data_in to exercise the S-box mapping.",
    "variation": "data_in: 0x00-0xFF, including both boundary values",
    "observation": "Observe result_out for each applied data_in value.",
    "branch_intent": "Exercises the complete byte-to-byte substitution mapping, covering every input value and both range boundaries."
  }
]
